             |                                              |       || ' AND element_type = 3 ), '                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
             |                                              |       || 'lines AS ( '                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
             |                                              |       || 'SELECT st_multi(ST_LineMerge(ST_Collect(ST_Simplify(e.geom,'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
             |                                              |       || tolerance || ')))) as g FROM '                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
             |                                              |       || quote_ident(topology_info.name) || '.edge e, '                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
